static GLint doubleBuffer(NSOpenGLPixelFormat *pf)
{
    GLint v = -1;
    [pf getValues:(void *)&v forAttribute:NSOpenGLPFADoubleBuffer forVirtualScreen:0];
    return v;
}

// QUIRK test: every archived cursor, standard or created from an image, decodes as the arrow
// cursor on macOS 10.14.4 (see the QUIRK comment in -[NSCursor initWithCoder:]).
static void test_quirk_cursor_decodes_as_arrow(void)
{
    const char *names[] = {"arrow", "ibeam", "crosshair", "pointingHand", "dragCopy", "custom image"};
    const char *hex[] = {fx_cursor_arrow, fx_cursor_ibeam, fx_cursor_crosshair, fx_cursor_pointingHand, fx_cursor_dragCopy, fx_cursor_custom};
    NSCursor *arrow = [NSCursor arrowCursor];
    for (size_t i = 0; i < sizeof(hex) / sizeof(hex[0]); i++)
    {
        NSCursor *c = decodeData(hexData(hex[i]));
        if (![c isKindOfClass:[NSCursor class]])
        {
            printf("FAIL cursor %s: not decoded\n", names[i]);
            failures++;
            continue;
        }
        if (c != arrow && !NSEqualPoints([c hotSpot], [arrow hotSpot]))
        {
            printf("FAIL cursor %s: not the arrow cursor\n", names[i]);
            failures++;
        }
    }
}

static void test_pixel_format(void)
{
    // a format that was not created from attribute data is archived with a nil NSData
    NSOpenGLPixelFormat *pf = decodeData(hexData(fx_glpf_1));
    CHECK([pf isKindOfClass:[NSOpenGLPixelFormat class]]);
    CHECK(doubleBuffer(pf) == 0);

    // attribute data {NSOpenGLPFADoubleBuffer, 8, 16, 0} is archived as big-endian words
    pf = decodeData(hexData(fx_glpf_data_native));
    CHECK([pf isKindOfClass:[NSOpenGLPixelFormat class]]);
    CHECK(doubleBuffer(pf) == 1);
}

static void test_gl_view(void)
{
    NSOpenGLView *v = decodeData(hexData(fx_glview_data_native));
    CHECK([v isKindOfClass:[NSOpenGLView class]]);
    CHECK(NSEqualRects([v frame], NSMakeRect(0, 0, 20, 20)));
    CHECK([[v pixelFormat] isKindOfClass:[NSOpenGLPixelFormat class]]);
    CHECK(doubleBuffer([v pixelFormat]) == 1);

    v = decodeData(hexData(fx_glview_nopf));
    CHECK([v isKindOfClass:[NSOpenGLView class]]);
    CHECK(NSEqualRects([v frame], NSMakeRect(0, 0, 10, 10)));
    CHECK([v pixelFormat] == nil);
}

int main(void)
{
    setvbuf(stdout, NULL, _IOLBF, 0);
    @autoreleasepool
    {
        NSApplicationLoad();
        test_quirk_cursor_decodes_as_arrow();
        test_pixel_format();
        test_gl_view();
    }
    printf(failures ? "FAIL\n" : "PASS\n");
    return failures != 0;
}
